  ('st-ex-temiru-1', 'sent-ex-temiru-1', 'en', 'I will try going to the new shop.', 'authored'),
  ('st-ex-temiru-2', 'sent-ex-temiru-2', 'en', 'I will try writing the letter in English.', 'authored'),
  ('st-ex-temiru-3', 'sent-ex-temiru-3', 'en', 'I will give that film a try.', 'authored'),
  ('st-ex-temiru-4', 'sent-ex-temiru-4', 'en', 'I will try asking my older brother.', 'authored'),
  ('st-ex-teikukuru-1', 'sent-ex-teikukuru-1', 'en', 'I will go and buy some bread.', 'authored'),
  ('st-ex-teikukuru-2', 'sent-ex-teikukuru-2', 'en', 'I will take an umbrella with me.', 'authored'),
  ('st-ex-teikukuru-3', 'sent-ex-teikukuru-3', 'en', 'I will run to the station.', 'authored'),
  ('st-ex-teikukuru-4', 'sent-ex-teikukuru-4', 'en', 'My little sister is coming home.', 'authored'),
  ('st-ex-tearu-1', 'sent-ex-tearu-1', 'en', 'The window has been left open.', 'authored'),
  ('st-ex-tearu-2', 'sent-ex-tearu-2', 'en', 'A book has been placed on the desk.', 'authored'),
  ('st-ex-tearu-3', 'sent-ex-tearu-3', 'en', 'The tickets have already been bought.', 'authored'),
  ('st-ex-tearu-4', 'sent-ex-tearu-4', 'en', 'Flowers have been arranged in the room.', 'authored'),
  ('st-ex-tameni-1', 'sent-ex-tameni-1', 'en', 'I need money in order to go to Japan.', 'authored'),
  ('st-ex-tameni-2', 'sent-ex-tameni-2', 'en', 'I study for the exam.', 'authored'),
  ('st-ex-tameni-3', 'sent-ex-tameni-3', 'en', 'I eat vegetables for the sake of my health.', 'authored'),
  ('st-ex-tameni-4', 'sent-ex-tameni-4', 'en', 'I work for my family.', 'authored'),
  ('st-ex-younimoku-1', 'sent-ex-younimoku-1', 'en', 'I write it in my notebook so that I do not forget.', 'authored'),
  ('st-ex-younimoku-2', 'sent-ex-younimoku-2', 'en', 'I sit at the front so that I can see.', 'authored'),
  ('st-ex-younimoku-3', 'sent-ex-younimoku-3', 'en', 'I leave early so as to be on time.', 'authored'),
  ('st-ex-younimoku-4', 'sent-ex-younimoku-4', 'en', 'I speak in plain words so that the students understand.', 'authored'),
  ('st-ex-youninaru-1', 'sent-ex-youninaru-1', 'en', 'I have got to the point where I can read kanji.', 'authored'),
  ('st-ex-youninaru-2', 'sent-ex-youninaru-2', 'en', 'I became able to swim in the sea.', 'authored'),
  ('st-ex-youninaru-3', 'sent-ex-youninaru-3', 'en', 'I want to become able to speak English.', 'authored'),
  ('st-ex-youninaru-4', 'sent-ex-youninaru-4', 'en', 'I have become able to get up early.', 'authored'),
  ('st-ex-younisuru-1', 'sent-ex-younisuru-1', 'en', 'I make a point of eating vegetables every day.', 'authored'),
  ('st-ex-younisuru-2', 'sent-ex-younisuru-2', 'en', 'I will make a point of going to bed early.', 'authored'),
  ('st-ex-younisuru-3', 'sent-ex-younisuru-3', 'en', 'I make sure not to be late for work.', 'authored'),
  ('st-ex-younisuru-4', 'sent-ex-younisuru-4', 'en', 'I make a point of running every morning.', 'authored'),
  ('st-ex-yasuinikui-1', 'sent-ex-yasuinikui-1', 'en', 'That book is easy to read.', 'authored'),
  ('st-ex-yasuinikui-2', 'sent-ex-yasuinikui-2', 'en', 'That kanji is hard to write.', 'authored'),
  ('st-ex-yasuinikui-3', 'sent-ex-yasuinikui-3', 'en', 'The teacher''s explanations are easy to understand.', 'authored'),
  ('st-ex-yasuinikui-4', 'sent-ex-yasuinikui-4', 'en', 'New shoes are hard to walk in.', 'authored'),
