  ('sent-ex-teikukuru-2', 'lang-ja', '傘を持っていく。', 'かさ お もって いく。', 'lvl-ja-n4', 'authored', true),
  ('sent-ex-teikukuru-3', 'lang-ja', '駅まで走っていく。', 'えき まで はしって いく。', 'lvl-ja-n4', 'authored', true),
  ('sent-ex-teikukuru-4', 'lang-ja', '妹が家に帰ってくる。', 'いもうと が いえ に かえって くる。', 'lvl-ja-n4', 'authored', true),
  -- te-aru
  ('sent-ex-tearu-1', 'lang-ja', '窓が開けてある。', 'まど が あけて ある。', 'lvl-ja-n4', 'authored', true),
  ('sent-ex-tearu-2', 'lang-ja', '机の上に本が置いてある。', 'つくえ の うえ に ほん が おいて ある。', 'lvl-ja-n4', 'authored', true),
